```java
import org.eclipse.jgit.api.*;
import org.eclipse.jgit.lib.Ref;

import java.io.File;
import java.io.IOException;

public class GitBranchTracker {

    public static void main(String[] args) throws IOException, GitAPIException {

        File gitDir = new File("/path/to/git/repo");
        try (Git git = Git.open(gitDir)) {

            // Fetch updates from remote repository
            git.fetch().setCheckFetchedObjects(true).call();

            // Get a list of all remote branches
            List<Ref> remoteBranches = git.branchList().setListMode(ListBranchCommand.ListMode.REMOTE).call();

            // Track each remote branch locally
            for (Ref branch : remoteBranches) {
                String branchName = branch.getName().replace("refs/remotes/", "");
                git.branchCreate().setName(branchName).setStartPoint(branch.getName()).call();
            }

            // Print a list of all local branches and their tracking references
            List<Ref> localBranches = git.branchList().setListMode(ListBranchCommand.ListMode.ALL).call();
            for (Ref branch : localBranches) {
                System.out.println(branch.getName() + " -> " + branch.getTrackingBranch());
            }
        }
    }
}
```

